<?php use Simit\Core\Csrf; ?>
<div class="toolbar"><div><h2><?=__('Pusat notifikasi','Notification center')?></h2><p class="muted"><?=__('Klik notifikasi untuk membuka halaman terkait.','Click a notification to open its related page.')?></p></div><form method="post"><?=Csrf::field()?><button class="btn ghost"><?=__('Tandai semua dibaca','Mark all as read')?></button></form></div><div class="panel notification-list"><?php foreach($rows as $row):?><a class="notification-row <?=$row['read_at']?'':'unread'?>" href="/notifikasi/buka/<?=$row['id']?>"><span class="notification-dot"></span><div><strong><?=e($row['title'])?></strong><p><?=e($row['message'])?></p><small><?=e($row['created_at'])?></small></div><span class="notification-arrow" aria-hidden="true">→</span></a><?php endforeach;?><?php if(!$rows):?><div class="empty"><?=__('Belum ada notifikasi.','No notifications yet.')?></div><?php endif;?></div>
